是祭坛第三层被「听雪」一剑斩碎之后，从阵眼里喷出来的东西——那是一股积了三千年的寒气，混着血煞，遇风即凝，落到地上就是一层薄薄的白。

陈渊踩着那层白，走到祭坛正中。

阵眼碎了。

九根石柱上的锁链尽断，柱顶空空荡荡。坛身那些原本透着暗红光的符文，此刻全都暗了下去，像一条条被晒干的虫，蜷在石头里。

可那片扭曲的空气还在。

就在祭坛顶端，九柱之间。

它比昨夜更大了，直径从一尺涨到了三尺，边缘还在极缓慢地往外扩。透过那片扭曲，看不见任何东西——不是黑，也不是白，是一种让人看一眼就想吐的「什么都没有」。

「这就是门？」洛清欢站在他身后，握剑的手出了汗。

「这是门缝。」

陈渊抬起手，往那片扭曲里探了半寸。

半寸而已。

他整个人就像被什么东西攥住了心脏，浑身血液在瞬间冻结，耳边炸开一片听不见的声音——不是震耳的响，是那种硬生生塞进颅骨里的、不属于人间的低语。

他把手抽回来。

掌心已经黑了一片。

那黑色在往里钻。

陈渊看了一眼，二话不说，把掌心按在自己左腕的胎记上。

暗金色的光一亮，那片黑色像遇见了火的蜡，一点点地退了回去。

